CREATE TABLE users (id UUID PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, avatar TEXT, level INT DEFAULT 1, xp INT DEFAULT 0, role VARCHAR(20) DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE conversations (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE messages (id UUID PRIMARY KEY, conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE courses (id UUID PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT, difficulty VARCHAR(30), xp_reward INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE labs (id UUID PRIMARY KEY, title VARCHAR(200) NOT NULL, category VARCHAR(50), difficulty VARCHAR(30), estimated_minutes INT, xp_reward INT DEFAULT 0, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE news (id UUID PRIMARY KEY, title TEXT NOT NULL, source VARCHAR(100), category VARCHAR(60), summary TEXT, published_at TIMESTAMP);
CREATE TABLE reports (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id), type VARCHAR(50), body TEXT, status VARCHAR(30) DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
